mapper.sql:
select p.page_id as pageId, p.page_code as pageCode, p.page_name as pageName, p.folder_id as folderId, f.folder_name as folderName, r.revision_id as revisionId, r.version_no as versionNo, r.version_no as version from dashboard_page p left join dashboard_page_folder f on f.folder_id = p.folder_id join dashboard_page_revision r on r.page_id = p.page_id and r.status = 'PUBLISHED' where p.status = '0' and p.is_deleted = '0' and r.revision_id = ( select r2.revision_id from dashboard_page_revision r2 where r2.page_id = p.page_id and r2.status = 'PUBLISHED' order by r2.version_no desc, r2.revision_id desc limit 1 )
and (p.page_code like concat('%', #{keyword}, '%') or p.page_name like concat('%', #{keyword}, '%'))
and p.folder_id = #{folderId}
and p.folder_id in #{id}
and 1 = 0
order by p.page_name asc, p.page_id asc

mapper.update:
update dashboard_page
page_name = #{pageName}, folder_id = #{folderId}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where page_id = #{pageId}

update dashboard_page_folder
folder_name = #{folderName}, parent_id = #{parentId}, sort_order = #{sortOrder}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where folder_id = #{folderId}

update dashboard_page_revision
set status = #{status}, publish_by = #{publishBy}, publish_time = now(), publish_note = #{publishNote}
where revision_id = #{revisionId}

mapper.sql:
select dataset_id as datasetId, dataset_code as datasetCode, dataset_name as datasetName, group_code as groupCode, data_type as dataType, config_json as configJson, field_schema_json as fieldSchemaJson, param_schema_json as paramSchemaJson, status, timeout_seconds as timeoutSeconds, refresh_seconds as refreshSeconds, last_test_at as lastTestAt, last_test_status as lastTestStatus, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from dashboard_dataset
and (dataset_code like concat('%', #{keyword}, '%') or dataset_name like concat('%', #{keyword}, '%'))
and data_type = #{dataType}
and group_code = #{groupCode}

mapper.select:
select dataset_id as datasetId, dataset_code as datasetCode, dataset_name as datasetName, group_code as groupCode, data_type as dataType, config_json as configJson, coalesce((select g.group_id from dashboard_dataset_group g where g.group_code = d.group_code), 0) as folderId, (select g.group_name from dashboard_dataset_group g where g.group_code = d.group_code) as folderName, field_schema_json as fieldSchemaJson, param_schema_json as paramSchemaJson, status, timeout_seconds as timeoutSeconds, refresh_seconds as refreshSeconds, last_test_at as lastTestAt, last_test_status as lastTestStatus, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from dashboard_dataset d
and (dataset_code like concat('%', #{keyword}, '%') or dataset_name like concat('%', #{keyword}, '%'))
and data_type = #{dataType} and group_code = #{groupCode}
and group_code in #{code}
and 1 = 0
order by dataset_id desc

mapper.update:
update dashboard_dataset
dataset_name = #{datasetName}, group_code = #{groupCode}, data_type = #{dataType}, config_json = #{configJson}, field_schema_json = #{fieldSchemaJson}, param_schema_json = #{paramSchemaJson}, last_test_status = null, last_test_at = null, status = #{status}, timeout_seconds = #{timeoutSeconds}, refresh_seconds = #{refreshSeconds}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where dataset_id = #{datasetId}

update dashboard_dataset_group
group_name = #{groupName}, parent_id = #{parentId}, sort_order = #{sortOrder}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where group_id = #{groupId}

update dashboard_resource_folder
folder_name = #{folderName}, parent_id = #{parentId}, sort_order = #{sortOrder}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where folder_id = #{folderId}

update dashboard_data_source
source_name = #{sourceName}, folder_id = #{folderId}, source_type = #{sourceType}, config_json = #{configJson}, secret_ciphertext = #{secretCiphertext}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where data_source_id = #{dataSourceId}

mapper.sql:
select a.asset_id as assetId, a.asset_code as assetCode, a.asset_name as assetName, a.folder_id as folderId, f.folder_name as folderName, a.asset_type as assetType, a.category, a.resource_path as resourcePath, a.mime_type as mimeType, a.file_size as fileSize, a.status, a.create_by as createBy, a.create_time as createTime, a.update_by as updateBy, a.update_time as updateTime, a.remark from dashboard_asset a left join dashboard_resource_folder f on f.folder_id = a.folder_id
and (a.asset_code like concat('%', #{keyword}, '%') or a.asset_name like concat('%', #{keyword}, '%') or a.category like concat('%', #{keyword}, '%'))
and a.asset_type = #{assetType} and a.folder_id = #{folderId}
and a.folder_id in #{id}
and 1 = 0
order by a.asset_id desc

mapper.update:
update dashboard_asset
asset_name = #{assetName}, folder_id = #{folderId}, category = #{category}, resource_path = #{resourcePath}, mime_type = #{mimeType}, file_size = #{fileSize}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where asset_id = #{assetId}

mapper.sql:
select m.map_id as mapId, m.map_code as mapCode, m.map_name as mapName, m.folder_id as folderId, f.folder_name as folderName, m.status, m.create_by as createBy, m.create_time as createTime, m.update_by as updateBy, m.update_time as updateTime, m.remark, char_length(m.geojson_json) as jsonSize from dashboard_map_resource m left join dashboard_resource_folder f on f.folder_id = m.folder_id
and (m.map_code like concat('%', #{keyword}, '%') or m.map_name like concat('%', #{keyword}, '%'))
and m.folder_id = #{folderId}
and m.folder_id in #{id}
and 1 = 0
order by m.map_id desc

select catalog.map_id as mapId, catalog.map_code as mapCode, catalog.map_name as mapName, catalog.folder_id as folderId, catalog.folder_name as folderName, catalog.status, catalog.create_by as createBy, catalog.create_time as createTime, catalog.update_by as updateBy, catalog.update_time as updateTime, catalog.remark, catalog.json_size as jsonSize, catalog.builtin from ( select null as map_id, 'demo-region' as map_code, '内置示例区域' as map_name, 0 as folder_id, null as folder_name, '0' as status, null as create_by, null as create_time, null as update_by, null as update_time, null as remark, null as json_size, 1 as builtin union all select m.map_id, m.map_code, m.map_name, m.folder_id, f.folder_name, m.status, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, char_length(m.geojson_json) as json_size, 0 as builtin from dashboard_map_resource m left join dashboard_resource_folder f on f.folder_id = m.folder_id ) catalog
and (locate(lower(#{keyword}), lower(catalog.map_code)) > 0 or locate(lower(#{keyword}), lower(catalog.map_name)) > 0)
and catalog.folder_id = #{folderId}
and catalog.folder_id in #{id}
and 1 = 0
order by catalog.builtin desc, catalog.map_id desc

mapper.update:
update dashboard_map_resource
map_name = #{mapName}, folder_id = #{folderId}, geojson_json = #{geojsonJson}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where map_id = #{mapId}
